using Godot;
using System;
public partial class ImageValueOperations
{
    private static readonly Vector3 Luminance=new(.2126f,.7152f,.0722f);
    private static Vector3 Legacy(Vector3 color,Operation operation)
    {
        double amount=operation.Amount;float a=(float)amount;var one=Vector3.One;double light=Math.Clamp(color.Dot(Luminance),0,1);switch(operation.Kind){case "multiply":return color*a;case "divide":return color/(float)Math.Max(.001,amount);case "add":case "brightness":return color+one*a;case "subtract":return color-one*a;case "exposure":return color*(float)Math.Pow(2,amount);case "power":case "gamma":double exponent=operation.Kind=="gamma"?1/Math.Max(.001,amount):Math.Max(.001,amount);return new Vector3((float)Math.Pow(Math.Max(0,color.X),exponent),(float)Math.Pow(Math.Max(0,color.Y),exponent),(float)Math.Pow(Math.Max(0,color.Z),exponent));case "snap":return(color*(float)Math.Max(1,amount)+one*.5f).Floor()/(float)Math.Max(1,amount);case "invert":return one-color;case "contrast":return(color-one*.5f)*a+one*.5f;case "saturation":return one*color.Dot(Luminance)*(1-a)+color*a;case "hue":return color.Rotated(one.Normalized(),a);case "minimum":return color.Min(one*a);case "maximum":return color.Max(one*a);case "temperature":return color+new Vector3(a,0,-a);case "tint":color.Y+=a;return color;case "red":color.X*=a;return color;case "green":color.Y*=a;return color;case "blue":color.Z*=a;return color;case "vibrance":float chroma=Math.Clamp(Math.Max(color.X,Math.Max(color.Y,color.Z))-Math.Min(color.X,Math.Min(color.Y,color.Z)),0,1);return(one*color.Dot(Luminance)).Lerp(color,1+a*(1-chroma));case "grayscale":return color.Lerp(one*color.Dot(Luminance),a);case "sepia":return color.Lerp(new Vector3(color.Dot(new Vector3(.393f,.769f,.189f)),color.Dot(new Vector3(.349f,.686f,.168f)),color.Dot(new Vector3(.272f,.534f,.131f))),a);case "posterize":return(color*(float)Math.Max(2,amount)+one*.5f).Floor()/(float)Math.Max(2,amount);case "solarize":return new Vector3(color.X>=amount?1-color.X:color.X,color.Y>=amount?1-color.Y:color.Y,color.Z>=amount?1-color.Z:color.Z);case "shadows":return color+one*(float)(amount*Math.Pow(1-light,2));case "highlights":return color+one*(float)(amount*Math.Pow(light,2));case "black_point":return(color-one*a)/(float)Math.Max(.001,1-amount);case "white_point":return color/(float)Math.Max(.001,amount);case "midtones":return color+one*(float)(amount*4*light*(1-light));case "lift":return color+(one-color)*a;case "fade":return color.Lerp(one*.5f,a);case "threshold":return color.Dot(Luminance)>=amount?one:Vector3.Zero;case "cyan_red":return color+new Vector3(a,-a*.5f,-a*.5f);case "magenta_green":return color+new Vector3(-a*.5f,a,-a*.5f);case "yellow_blue":return color+new Vector3(-a*.5f,-a*.5f,a);case "shadow_warmth":return color+new Vector3(a,0,-a)*(float)Math.Pow(1-light,2);case "highlight_warmth":return color+new Vector3(a,0,-a)*(float)Math.Pow(light,2);case "colorize":return color.Lerp(new Vector3(1.35f,.95f,.65f)*color.Dot(Luminance),a);default:return color;}
    }
}
